<?php require __DIR__.'/includes/bootstrap.php';requireRole('attendee');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed.');}$id=(int)($_POST['event_id']??0);$action=$_POST['action']??'';$statement=$pdo->prepare("SELECT * FROM events WHERE event_id=? AND status='approved'");$statement->execute([$id]);$event=$statement->fetch();if(!$event){flash('This event is not available.','error');redirect('index.php');}$info=eventCapacityInfo($pdo,$id);$userId=currentUser()['user_id'];
if($action==='book'){if($info['bookings'] >= (int)$event['capacity']){flash('This event is now full. You can join the waiting list.','error');redirect('event.php?id='.$id);}try{$statement=$pdo->prepare('INSERT INTO bookings (event_id,user_id) VALUES (?,?)');$statement->execute([$id,$userId]);flash('Your place is confirmed.');}catch(PDOException $e){flash('You already have a booking for this event.','error');}}
elseif($action==='wait'){if($info['bookings'] < (int)$event['capacity']){flash('A place is available; book it instead.','error');redirect('event.php?id='.$id);}try{$statement=$pdo->prepare('INSERT INTO waiting_list (event_id,user_id) VALUES (?,?)');$statement->execute([$id,$userId]);flash('You joined the waiting list.');}catch(PDOException $e){flash('You are already in the waiting list.','error');}}
else{http_response_code(400);exit('Invalid action.');}redirect('event.php?id='.$id);
